"""Bounded source-media candidates at unchanged catalog geometry; no engine admission."""
from pathlib import Path
import argparse,hashlib,json,shutil
from PIL import Image,ImageDraw
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
def write(p,v):p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(v,indent=2)+'\n')
def build(repo,catalog,background,root):
 ids=['torrey_pine','california_bush_sunflower','san_diego_monkeyflower','blue_eyed_grass','cedar_feeder','bench','pedestal_birdbath'];all_entries=json.loads(catalog.read_text());entries=[next(e for e in all_entries if e['id']==i)for i in ids];out=root/'admission';out.mkdir(exist_ok=True);records=[];positions={'torrey_pine':[180,450],'california_bush_sunflower':[370,450],'san_diego_monkeyflower':[500,410],'blue_eyed_grass':[540,460],'cedar_feeder':[700,445],'bench':[600,515],'pedestal_birdbath':[820,500]}
 for e in entries:
  original=repo/e['sourcePath'];assert sha(original)==e['sourceSha256'];src=Image.open(original).convert('RGBA');world=(e['width'],e['height']);im=src.resize(world,Image.Resampling.NEAREST);p=out/'sprites'/(e['id']+'.q11_catalog_display_v1.png');p.parent.mkdir(exist_ok=True);im.save(p);native=out/'originals'/original.name;native.parent.mkdir(exist_ok=True);shutil.copyfile(original,native);alpha=im.getchannel('A');maxa=alpha.getextrema()[1];x,y=next((x,y)for y in range(im.height)for x in range(im.width)if alpha.getpixel((x,y))==maxa)
  manifest={'schemaVersion':1,'profile':'chirp-texture-review-v1','scope':'review-only','approval':'unreviewed','activation':'none','source':{'sha256':sha(p),'creator':'ChirpNeighbors source production','tool':'Pillow nearest catalog-size source adapter','toolVersion':'qualification11','rights':'unreviewed','fidelity':'unreviewed'},'atlas':{'width':world[0],'height':world[1],'alpha':'straight-rgba8','colorSpace':'srgb'},'frames':[{'id':'rest','sourceRect':{'x':0,'y':0,'width':world[0],'height':world[1]},'canvas':{'width':world[0],'height':world[1]},'trim':{'x':0,'y':0},'pivot':e['pivot'],'contacts':[{'id':'visual-alpha-sample','x':x,'y':y}],'world':{'width':world[0],'height':world[1]},'sourcePixelsPerWorldUnit':1}],'clips':[{'id':'idle','tickRate':30,'loop':True,'frames':[{'frameId':'rest','durationTicks':30}]}]};mp=out/'manifests'/(e['id']+'.json');write(mp,manifest)
  raw=json.loads(json.dumps(manifest));raw['source']['sha256']=e['sourceSha256'];raw['atlas'].update(width=src.width,height=src.height);raw['frames'][0]['canvas'].update(width=src.width,height=src.height);raw['frames'][0]['sourceRect'].update(width=src.width,height=src.height);raw['frames'][0]['sourcePixelsPerWorldUnit']=src.width/world[0];raw['frames'][0]['pivot']={'x':round(e['pivot']['x']*src.width/world[0]),'y':round(e['pivot']['y']*src.height/world[1])};write(out/'native-preflight-studies'/(e['id']+'.json'),raw)
  masks={}
  for name,a in [('soft_alpha',alpha),('coverage128',alpha.point(lambda a:255 if a>=128 else 0))]:
   f=out/'masks'/(e['id']+'.'+name+'.png');f.parent.mkdir(exist_ok=True);a.save(f);masks[name]={'file':str(f.relative_to(out)),'sha256':sha(f),'semantics':'Visual raster coverage only; no collision/support/physical authority'}
  records.append({'catalog_id':e['id'],'asset_id':e['assetId'],'variant_id':e['variantId'],'candidate_revision':'q11_catalog_display_v1','original':{'file':str(native.relative_to(out)),'canonical_path':e['sourcePath'],'sha256':e['sourceSha256'],'dimensions_px':list(src.size)},'display_sprite':{'file':str(p.relative_to(out)),'sha256':sha(p),'dimensions_px':list(world),'mode':'RGBA','alpha_extrema':list(alpha.getextrema())},'manifest':str(mp.relative_to(out)),'masks':masks,'catalog_record_exact':e,'catalog_geometry_changed':False,'diagnostic_root_world':positions[e['id']],'derivative_operation':'RGBA decode then one NEAREST resize from exact source to existing catalog width/height;1sourcepixel/worldunit; no art repaint/crop/alpha threshold. Original unchanged.','normal_display_pixels_equal_native_catalog_resize':True,'functional_contact_authority':'Visual alpha sample required by media profile; original catalog slots/footprint retained as unvalidated references, never inferred from masks.','source_art_grade':'pass_scoped_static_visual','media_candidate_status':'Await actual pinned parser/preflight receipt; not admitted','physical_geometry_reviewed':False,'runtime_admitted':False})
 bg=Image.open(background).convert('RGBA');assert bg.size==(960,540);clean=bg.copy();overlay=ImageDraw.Draw(clean);no_actors=bg.tobytes()
 for r in sorted(records,key=lambda r:(r['diagnostic_root_world'][1],r['catalog_id'])):
  e=r['catalog_record_exact'];im=Image.open(out/r['display_sprite']['file']).convert('RGBA');xy=(r['diagnostic_root_world'][0]-e['pivot']['x'],r['diagnostic_root_world'][1]-e['pivot']['y']);clean.alpha_composite(im,xy)
 prev=root/'root/previews';prev.mkdir(parents=True,exist_ok=True);clean.save(prev/'coherent-catalog-set-960.png');clean.resize((384,216),Image.Resampling.NEAREST).save(prev/'coherent-catalog-set-384.png');annot=clean.copy();d=ImageDraw.Draw(annot)
 for r in records:
  e=r['catalog_record_exact'];x,y=r['diagnostic_root_world'];xy=(x-e['pivot']['x'],y-e['pivot']['y']);d.rectangle((xy[0],xy[1],xy[0]+e['width']-1,xy[1]+e['height']-1),outline='#e3a32e');d.line((x-5,y,x+5,y),fill='#f42475',width=1);d.line((x,y-5,x,y+5),fill='#f42475',width=1);d.text((xy[0],xy[1]-12),e['id'],fill='#fff8d8')
 annot.save(prev/'coherent-catalog-geometry-overlay.png');clean.resize((900,506),Image.Resampling.LANCZOS).convert('RGB').save(prev/'Qualification11-Index.jpg',quality=86)
 for r in records:
  e=r['catalog_record_exact'];im=Image.open(out/r['display_sprite']['file']).convert('RGBA');native=Image.open(out/r['original']['file']).convert('RGBA');assert im.tobytes()==native.resize((e['width'],e['height']),Image.Resampling.NEAREST).tobytes()
 write(out/'admission-packet.json',{'role':'Source-only media candidates for existing catalog IDs; no replacement catalog','candidate_revision':'qualification11_catalog_display_v1','source_catalog_sha256':sha(catalog),'instances':records,'world_canvas_px':[960,540],'background_reference':{'file_name':background.name,'sha256':sha(background),'source_release_unchanged':'Integration10 v1,sourceRelease3de66c0b4d5278196a493cd7637f11fd2000ec928198ef82d62f9f3cab139e57'},'display_density':{'native_to_review':'Explicit nearest resize to current catalog raster size','review_pixels_per_world_unit':1,'mobile_scale':.4,'shared_logical_pixel_style_approved':False,'metres_or_physical_size_calibrated':False},'source_art_modified':False,'new_generation_calls':0,'engine_files_changed':0,'runtime_admitted':False,'geometry_authority':'Existing catalog data preserved as reference, not newly reviewed geometry. No support/collision/perch promotion.','reassembly':'Render displayed sprites at exact declared world size/pivot; source originals retained and hash-bound.'})
 print(json.dumps({'passing_static_assets':len(records),'separate_media_candidates':len(records),'new_generation':0,'current_catalog_geometry_unchanged':True}))
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--repo',type=Path,required=True);p.add_argument('--catalog',type=Path,required=True);p.add_argument('--background',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();build(a.repo,a.catalog,a.background,a.output)
